"""Fused candidate fz_maj3: 3-stage 5-input majority: x ^= maj(ra,rb,rc,rd,re) ^ rf ^ rg (generated by gen_fused1.py)."""
import numpy as np

M64 = np.uint64(0xFFFFFFFFFFFFFFFF)

def _rotl(x, r):
    r %= 64
    if r == 0:
        return x
    return ((x << np.uint64(r)) | (x >> np.uint64(64 - r))) & M64

def _maj5(a, b, c, d, e):
    return ((a&b)|(a&c)|(a&d)|(a&e)|(b&c)|(b&d)|(b&e)|(c&d)|(c&e)|(d&e)) & M64

STAGES = [(1, 8, 15, 29, 43, 7, 23), (5, 13, 25, 39, 53, 11, 31), (9, 19, 33, 47, 59, 17, 37)]

def mix_np(V, K):
    x = np.asarray(V, dtype=np.uint64); k = np.asarray(K, dtype=np.uint64)
    x = (x ^ k) & M64
    # stage 0
    r0,r1,r2,r3,r4,r5,r6 = _rotl(x,1), _rotl(x,8), _rotl(x,15), _rotl(x,29), _rotl(x,43), _rotl(x,7), _rotl(x,23)
    x = (x ^ _maj5(r0,r1,r2,r3,r4) ^ r5 ^ r6) & M64
    # stage 1
    r0,r1,r2,r3,r4,r5,r6 = _rotl(x,5), _rotl(x,13), _rotl(x,25), _rotl(x,39), _rotl(x,53), _rotl(x,11), _rotl(x,31)
    x = (x ^ _maj5(r0,r1,r2,r3,r4) ^ r5 ^ r6) & M64
    # stage 2
    r0,r1,r2,r3,r4,r5,r6 = _rotl(x,9), _rotl(x,19), _rotl(x,33), _rotl(x,47), _rotl(x,59), _rotl(x,17), _rotl(x,37)
    x = (x ^ _maj5(r0,r1,r2,r3,r4) ^ r5 ^ r6) & M64
    x = (x ^ _rotl(k, 13)) & M64
    return x & M64
def mix(v, k):
    return int(mix_np(np.uint64(v), np.uint64(k)))
